<x-workspace-layout><div class="workspace-heading"><div><p class="eyebrow">{{ $quote->status }}</p><h1>{{ $quote->number }}</h1><p>For {{ $quote->customer->name }} · {{ $quote->currency }} {{ number_format($quote->total,2) }}</p></div><div class="actions"><a class="button secondary" target="_blank" href="{{ route('quotes.print',$quote) }}">Print / save PDF</a>@if($quote->status==='draft')<form method="POST" action="{{ route('quotes.approve',$quote) }}">@csrf<button class="button">Approve quote</button></form>@elseif($quote->status==='approved')<form method="POST" action="{{ route('quotes.send',$quote) }}">@csrf<button class="button">Send to customer</button></form>@elseif($quote->status==='accepted')<a class="button" href="{{ route('bookings.create',$quote) }}">Schedule booking</a>@endif</div></div><div class="detail-grid"><section class="card"><h2>Quote total</h2><div class="quote-total">{{ $quote->currency }} {{ number_format($quote->total,2) }}</div><table><tbody>@foreach($quote->items as $item)<tr><td>{{ $item->description }}</td><td>{{ $item->quantity }} × {{ number_format($item->unit_price,2) }}</td><td>{{ number_format($item->total,2) }}</td></tr>@endforeach<tr><td colspan="2">Subtotal</td><td>{{ number_format($quote->subtotal,2) }}</td></tr><tr><td colspan="2">Tax ({{ $quote->tax_rate }}%)</td><td>{{ number_format($quote->tax_total,2) }}</td></tr></tbody></table></section><section class="card"><h2>Customer delivery</h2><p>Secure link expires {{ $quote->public_token_expires_at?->format('j M Y') }}.</p>@if(in_array($quote->status,['approved','sent','accepted','declined']))<label>Customer link<input readonly value="{{ route('public.quote',$quote->public_token) }}"></label>@endif<p><b>Notes</b><br>{{ $quote->notes ?: 'None' }}</p><p><b>Terms</b><br>{{ $quote->terms ?: 'None supplied' }}</p></section></div><section class="card"><h2>Quote history</h2>@foreach($quote->events as $event)<div class="list-row"><div><b>{{ str_replace('_',' ',ucfirst($event->event)) }}</